import React, { createContext, useContext, useState, useEffect } from 'react';
import axios from 'axios';

const FeatureFlagContext = createContext();

export const FeatureFlagProvider = ({ children }) => {
  const [flags, setFlags] = useState({
    // ALL NEW FEATURES DISABLED BY DEFAULT FOR BACKWARD COMPATIBILITY
    locationServices: false,
    passportMode: false,
    realTimeNotifications: false,
    advancedAnalytics: false,
    nearbyMap: false,
    rabbitMQ: false,
  });

  useEffect(() => {
    // Load feature flags from server (safe, non-blocking)
    loadFeatureFlags();
  }, []);

  const loadFeatureFlags = async () => {
    try {
      // Non-blocking - app works even if this fails
      const backendHost = window.location.hostname;
      const API_URL = process.env.REACT_APP_API_URL || `http://${backendHost}:5000`;

      const response = await axios.get(`${API_URL}/api/v2/features`);
      if (response.data) {
        setFlags(prev => ({ ...prev, ...response.data }));
      }
    } catch (error) {
      // Continue with defaults (all disabled)
      console.info('Feature flags not available, using defaults');
    }
  };

  const isEnabled = (flag) => {
    return flags[flag] === true;
  };

  return (
    <FeatureFlagContext.Provider value={{ isEnabled, flags }}>
      {children}
    </FeatureFlagContext.Provider>
  );
};

export const useFeatureFlag = () => useContext(FeatureFlagContext);
